/**
 * No-GPU fallback. When the browser offers neither WebGPU nor WebGL2 (no
 * graphics acceleration: virtual machines, remote desktops, blocklisted
 * drivers), live rendering of tens of millions of stars is impossible. The
 * page then says so plainly, explains how to turn acceleration on, and shows
 * every station as a still pre-rendered by the same program
 * (web/tools/stills.mjs, tools/stills.py), with the same card text and numbers (claims.json).
 * Loaded lazily: none of the 3-D code is downloaded on this path.
 */
import './fallback.css';
import { el } from './dom';
import { u } from '../app/base';
import { STATIONS, type Claim, type Claims } from '../content/stations';

export interface Capability {
  webgpu: string;
  webgl2: string;
}

function stationBlock(id: string, claims: Claims): HTMLElement | null {
  const s = STATIONS.find((x) => x.id === id);
  if (!s) return null;
  const c = s.card(claims);
  const img = el('img', {
    src: u(`stills/${id}-1920.jpg`),
    srcset: `${u(`stills/${id}-960.jpg`)} 960w, ${u(`stills/${id}-1920.jpg`)} 1920w`,
    sizes: '(max-width: 900px) 100vw, 64vw',
    alt: `${c.title}（预渲染画面）`,
    loading: 'lazy',
    decoding: 'async',
    width: 1920,
    height: 1080,
  });
  return el('section', { class: 'fb-station' },
    el('figure', { class: 'fb-still' }, img),
    el('div', { class: 'fb-text' },
      el('div', { class: 'fb-kicker' }, c.kicker),
      el('h2', {}, c.title),
      c.figure ? el('div', { class: 'fb-figure' }, c.figure.value, c.figure.unit ? el('small', {}, c.figure.unit) : null) : null,
      c.quote ? el('blockquote', {}, c.quote.text, el('cite', {}, c.quote.cite)) : null,
      ...(c.lines ?? []).map((l) => el('p', {}, l)),
      c.how?.length ? el('details', {}, el('summary', {}, '这个结论怎么算的'), ...c.how.map((h) => el('p', {}, h))) : null,
    ),
  );
}

export async function showFallback(cap: Capability): Promise<void> {
  document.documentElement.dataset.theme = 'obs';
  document.getElementById('sky')?.remove();
  document.body.classList.add('fb-body');
  let claims: Claims = new Map();
  try {
    const j = (await (await fetch(u('data/claims.json'))).json()) as { claims: Claim[] };
    claims = new Map(j.claims.map((c) => [c.id, c]));
  } catch {
    /* the stills and the text still work without the numbers */
  }
  const size = claims.get('catalog_size')?.display ?? '3384 万颗';
  const root = el('main', { class: 'fb' },
    el('header', { class: 'fb-head' },
      el('h1', {}, '星空的时间机器'),
      el('p', { class: 'fb-sub' }, `用 ${size}恒星的六维数据，倒放与快进中国人的星空。`),
    ),
    el('aside', { class: 'fb-notice', role: 'status' },
      el('h2', {}, '这台电脑的浏览器没有可用的图形加速'),
      el('p', {}, '这件作品在浏览器里实时渲染数千万颗恒星，需要 WebGPU 或 WebGL2。当前浏览器两者都不可用，常见于虚拟机、远程桌面，或显卡加速被关闭。'),
      el('ol', {},
        el('li', {}, 'Chrome / Edge：设置 → 系统 → 打开“使用图形加速（如果可用）”，然后重启浏览器。'),
        el('li', {}, '在地址栏打开 chrome://gpu，确认 WebGL2 或 WebGPU 显示为“Hardware accelerated”。'),
        el('li', {}, '仍不行时，请更新显卡驱动，或换一台有独立显卡或核显的电脑。'),
      ),
      el('p', { class: 'fb-tech' }, `检测结果：WebGPU ${cap.webgpu}；WebGL2 ${cap.webgl2}`),
      el('p', {}, '下面是同一程序在支持的电脑上渲染的画面（预渲染静帧，不是实时画面），以及每个站点的说明。'),
    ),
    ...STATIONS.map((s) => stationBlock(s.id, claims)),
    el('footer', { class: 'fb-foot' },
      el('p', {}, '数据：Gaia DR3（ESA/Gaia/DPAC，CC BY-SA 3.0 IGO）；距离：Bailer-Jones 等 2021；亮星：HYG v4.1（CC BY-SA 4.0）；星官：Stellarium skycultures（CC BY-SA）；古籍：维基文库。'),
    ),
  );
  document.body.append(root);
}
